using System.Reflection;
using System.Text.Json;
using Studio.Core;
using Studio.Raple;
using TKR.WorldServer.core.objects;
using TKR.WorldServer.core.worlds;

var adapter=new RapleAdapter(Path.GetFullPath(args.FirstOrDefault()??"../raple-realms-7-server"));var checks=0;
void Check(bool value,string label){if(!value)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}
void Reject(Action action,string label){try{action();}catch(Exception e)when(e is ArgumentException or InvalidOperationException){Check(true,label);return;}throw new Exception("Expected rejection: "+label);}
const string entity="Cave Pirate Brawler";const string floor="Arena Dirt";var target=NativeArena.Grounds().First(g=>g.CompletePlayerSupport&&!g.NoWalk&&g.Id!=floor);var other=NativeArena.Grounds().First(g=>g.CompletePlayerSupport&&!g.NoWalk&&g.Id!=floor&&g.Id!=target.Id);
string Q(string text)=>JsonSerializer.Serialize(text);
string Wave(double start=0,double end=3,int duration=300,int delay=0,bool restore=false,bool lab=true)=>$"new TerrainWave({Q(target.Id)},new[]{{{Q(floor)}}},{start},{end},{duration},delayMs:{delay},restoreOnExit:{restore.ToString().ToLowerInvariant()},allowBossLab:{lab.ToString().ToLowerInvariant()})";
BehaviorDocument Doc(string body)=>new("class Fixture{void Build(){db.Init(\""+entity+"\",new State(\"wave\","+body+"));}}",adapter);
World World(EncounterSession session){var engine=typeof(EncounterSession).GetField("engine",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(session)!;return(World)engine.GetType().GetField("World")!.GetValue(engine)!;}
Enemy Boss(EncounterSession session)=>World(session).Enemies.Values.First(e=>e.ObjectDesc.IdName==entity);
int Changed(EncounterSession session)=>session.Arena.Cells.Count(c=>c.GroundType==target.Type);
Check(adapter.Primitives.Single(p=>p.Name=="TerrainWave").Simulatable&&adapter.Overloads("TerrainWave").Single().Parameters.Any(p=>p.Name=="from"&&p.Type=="string[]"),"TerrainWave authoring retains the original constructor and ground-array input");
Check(adapter.Callbacks("TerrainWave").Select(c=>c.Stage).SequenceEqual(new[]{"Entry","Ongoing","Exit","Death"}),"Native lifecycle metadata includes entry, ongoing mutation and exit/death restoration");
var timingDoc=Doc(Wave(delay:200));var pattern=adapter.ReadTerrainWave(timingDoc,timingDoc.AllNodes.Single(n=>n.Kind=="TerrainWave"))!;
Check(RapleAdapter.TerrainWaveFrontRadius(pattern,100)==0&&RapleAdapter.TerrainWaveFrontRadius(pattern,350)==1.5&&RapleAdapter.TerrainWaveFrontRadius(pattern,900)==3,"Timing preview invokes the original delayed/clamped linear front helper");
Check(RapleAdapter.TerrainWaveFrontRadius(pattern with{Delay=int.MaxValue,Duration=int.MaxValue},(long)int.MaxValue*2)==3,"Native timing helper retains full integer delay/duration values without summed-time overflow");
using(var native=new EncounterSession(adapter,Doc(Wave()),entity,7,new(Invulnerable:true)))
{
    native.Advance(new(),100);Check(Changed(native)==1,"Entry's first tick includes the initial zero-radius center");native.Advance(new(),100);Check(Changed(native)==5,"One elapsed native tick crosses all tile centers within one tile");native.Advance(new(),100);Check(Changed(native)==13,"Later ticks convert the complete crossed annulus without skipping boundary cells");native.Advance(new(),100);Check(Changed(native)==29,"The completed radius-three wave matches the exact native tile-center disk");var before=native.Arena;native.Advance(new(),300);Check(ReferenceEquals(before,native.Arena),"Completed native waves stop changing map cells");
}
using(var native=new EncounterSession(adapter,Doc(Wave(3,0)),entity,7,new(Invulnerable:true))){native.Advance(new(),400);Check(Changed(native)==29,"An inward wave covers its initial outer boundary through the center");}
using(var native=new EncounterSession(adapter,Doc(Wave(delay:200)),entity,7,new(Invulnerable:true))){native.Advance(new(),100);Check(Changed(native)==0,"Native delay suppresses early ground mutation");native.Advance(new(),200);Check(Changed(native)==1,"At the delay boundary the first tick still crosses the initial zero-radius center");}
using(var native=new EncounterSession(adapter,Doc(Wave(lab:false)),entity,7,new(Invulnerable:true))){native.Advance(new(),400);Check(Changed(native)==0,"The actual Boss Lab exclusion remains the native default behavior");}
using(var native=new EncounterSession(adapter,Doc(Wave()),entity,7,new(Invulnerable:true))){native.Advance(new(),100);var boss=Boss(native);boss.Move(68.5f,64.5f);native.Advance(new(),300);Check(World(native).Map[64,64].TileId==target.Type&&World(native).Map[68,64].TileId!=target.Type,"Wave geometry remains anchored to original spawn despite live host movement");}
using(var native=new EncounterSession(adapter,Doc(Wave()),entity,7,new(Invulnerable:true),arena:new(){Tiles=[new(64,64,other.Id)]})){native.Advance(new(),400);Check(Changed(native)==28&&World(native).Map[64,64].TileId==other.Type,"Only actual selected source grounds are replaced; unmatched native cells remain intact");}
string Transition(bool restore)=>"new State(new State(\"wave\","+Wave(restore:restore)+",new TimedTransition(400,\"done\")),new State(\"done\"))";
BehaviorDocument RootDoc(string root)=>new("class Fixture{void Build(){db.Init(\""+entity+"\","+root+");}}",adapter);
using(var native=new EncounterSession(adapter,RootDoc(Transition(true)),entity,7,new(Invulnerable:true))){native.Advance(new(),400);var updates=World(native).Map[64,64].UpdateCount;Check(Changed(native)==29,"Restoring waves still finish their real mutation before exit");World(native).Map[64,64].TileId=other.Type;native.Advance(new(),200);Check(Changed(native)==0&&World(native).Map[64,64].TileId==NativeArena.GroundType(floor)&&World(native).Map[64,64].UpdateCount>updates,"Native exit restores original ground IDs, overwrites later edits and increments tile update counts");}
using(var native=new EncounterSession(adapter,RootDoc(Transition(false)),entity,7,new(Invulnerable:true))){native.Advance(new(),500);Check(Changed(native)==29,"Default non-restoring terrain persists after the phase exits");}
using(var native=new EncounterSession(adapter,Doc(Wave(restore:true)),entity,7,new(Invulnerable:true))){native.Advance(new(),400);native.SetBossHpFraction(0);native.Advance(new(Attack:true),1000);Check(native.BossHp==0&&Changed(native)==0,"Actual weapon-triggered native death restores recorded wave grounds");}
var doc=Doc(Wave());var node=doc.AllNodes.Single(n=>n.Kind=="TerrainWave");var identities=doc.Identities;adapter.EditTerrainWaveGround(doc,entity,node.Id,doc.Revision,PhaseChoiceEdit.Add,0,other.Id);Check(adapter.TerrainWaveGrounds(doc,doc.Find(node.Id))!.SequenceEqual(new[]{floor,other.Id}),"Source-ground authoring adds exact XML IDs without inventing a filter");adapter.EditTerrainWaveGround(doc,entity,node.Id,doc.Revision,PhaseChoiceEdit.Up,1);Check(adapter.TerrainWaveGrounds(doc,doc.Find(node.Id))!.First()==other.Id,"Source-ground reorder preserves actual input slots");adapter.EditTerrainWaveGround(doc,entity,node.Id,doc.Revision,PhaseChoiceEdit.Remove,0);Reject(()=>adapter.EditTerrainWaveGround(doc,entity,node.Id,doc.Revision,PhaseChoiceEdit.Remove,0),"Native source ground lists keep their nonempty constructor contract");
adapter.SetTerrainWaveGround(doc,entity,node.Id,doc.Revision,other.Id);Check(adapter.ReadTerrainWave(doc,doc.Find(node.Id))!.To==other.Id,"Destination selection uses the exact native XML ground ID");var accepted=doc.Source;var revision=doc.Revision;Reject(()=>adapter.SetTerrainWaveGround(doc,entity,node.Id,revision-1,target.Id),"Stale terrain selections reject atomically");doc.LockedNodes.Add(node.Id);Reject(()=>adapter.SetTerrainWaveGround(doc,entity,node.Id,revision,target.Id),"Terrain region locks protect native ground edits");doc.LockedNodes.Clear();Reject(()=>adapter.SetTerrainWaveGround(doc,entity,node.Id,revision,"missing terrain"),"Unknown destination ground XML rejects before native entry lookup");Check(doc.Source==accepted&&doc.Revision==revision,"Rejected terrain edits preserve accepted source and revision");while(doc.Source!=Doc(Wave()).Source)if(!doc.Undo())throw new Exception("Could not restore terrain edits");Check(doc.Identities.SequenceEqual(identities),"Terrain history restores original source and identities");
Check(adapter.Validate(Doc(Wave(duration:99)),entity).Any(d=>d.IsError)&&adapter.Validate(Doc(Wave(delay:-1)),entity).Any(d=>d.IsError)&&adapter.Validate(Doc(Wave(start:-1)),entity).Any(d=>d.IsError),"Known native duration/delay/radius constructor limits reject before playback");
Check(adapter.Validate(Doc(Wave().Replace("new[]{"+Q(floor)+"}","null")),entity).Any(d=>d.IsError)&&adapter.Validate(Doc(Wave().Replace("new[]{"+Q(floor)+"}","new string[]{null}")),entity).Any(d=>d.IsError),"Null source lists and null source IDs reject before native lookup");
Check(adapter.Validate(Doc(Wave().Replace(Q(target.Id),Q("missing ground"))),entity).Any(d=>d.IsError),"Unknown destination XML rejects before entry");
var sourceFile=adapter.Catalog().Single(e=>e.Id==entity).SourceFile;var supplied=File.ReadAllText(sourceFile);var source="using TKR.WorldServer.logic.behaviors;using TKR.WorldServer.logic.transitions;namespace TKR.WorldServer.logic{public partial class BehaviorDb{private _ StudioTerrainWave=()=>Behav().Init(\""+entity+"\","+Transition(true)+");}}";var project=new StudioProject{SourceFile=sourceFile,Source=source,EntityId=entity,Player=new(Invulnerable:true),Seed=7};
using var literal=new EncounterSession(adapter,RootDoc(Transition(true)),entity,7,project.Player);await using var compiled=await CompiledRuntime.StartAsync(adapter.ServerRoot,project);foreach(var duration in new[]{100,300,200}){literal.Advance(new(),duration);await compiled.AdvanceAsync(new(),duration);Check(literal.Arena.Cells.SequenceEqual(compiled.Arena.Cells)&&literal.Arena.GroundType==compiled.Arena.GroundType,"Literal and compiled native terrain mutation/restoration retain identical complete map snapshots at "+literal.Ms+" ms");}
var output=Path.GetFullPath(".artifacts/terrain-wave");Directory.CreateDirectory(output);var path=Path.Combine(output,"terrain.rbs");BehaviorDocument.Save(path,project with{Identities=new BehaviorDocument(source,adapter,sourceFile:sourceFile).Identities});var saved=BehaviorDocument.Load(path);Check(new BehaviorDocument(saved.Source,adapter,saved.Identities,sourceFile).Identities.SequenceEqual(saved.Identities),"Terrain source and native identities survive save/reopen");Check(File.ReadAllText(sourceFile)==supplied,"Terrain authoring and native execution leave supplied game source unchanged");Console.WriteLine($"{checks} native terrain wave checks passed.");
